class _FileFormState extends State<FileForm>{late TextEditingController title,type,deal,area,price,address,owner,phone,description,link,apiKey,accessToken;bool loading=false;String message='';@override void initState(){super.initState();final x=widget.existing??{};title=_ctl(x['title']);type=_ctl(x['type']??'آپارتمان');deal=_ctl(x['deal']??'فروش');area=_ctl(x['area']);price=_ctl(x['price']);address=_ctl(x['address']);owner=_ctl(x['ownerName']);phone=_ctl(x['ownerPhone']);description=_ctl(x['description']);link=_ctl(x['divarLink']);apiKey=TextEditingController();accessToken=TextEditingController();}TextEditingController _ctl(dynamic v)=>TextEditingController(text:v==null?'':'$v');String? token(){final a=RegExp(r'divar\.ir/v/([A-Za-z0-9_-]{6,20})').firstMatch(link.text);if(a!=null)return a.group(1);final b=RegExp(r'divar\.ir/[^/]+/[^/]+/([A-Za-z0-9_-]{6,20})').firstMatch(link.text);return b?.group(1);}Future<void> importDivar()async{final t=token();if(t==null){setState(()=>message='لینک دیوار معتبر نیست');return;}if(apiKey.text.trim().isEmpty){setState(()=>message='API Key رسمی دیوار را وارد کن');return;}setState(()=>loading=true);try{final r=await http.get(Uri.parse('https://open-api.divar.ir/v1/open-platform/finder/post/$t'),headers:{'x-api-key':apiKey.text.trim()});final j=jsonDecode(r.body);if(r.statusCode<200||r.statusCode>299)throw Exception(j['message']??r.statusCode);final d=Map<String,dynamic>.from(j['data']??{});final p=d['price'];final imgs=d['images'] is List?(d['images'] as List).map((e)=>'$e').toList():<String>[];title.text='${d['title']??d['prefilled_title']??''}';area.text='${d['size']??d['area']??''}';price.text=p is Map?'${p['value']??''}':'${p??''}';address.text='${j['address']??j['district']??address.text}';description.text='${d['description']??''}';await DB.set('pending_images',jsonEncode(imgs));setState(()=>message='اطلاعات عمومی آگهی وارد شد؛ شماره خصوصی مالک از GET_POST برنمی‌گردد.');}catch(e){setState(()=>message='خطا: $e');}finally{if(mounted